-- Athena saved query (Product_B2C_Intl)
-- ID: 9dcb7add-b3ac-4485-bf6a-55c5a5d21625
-- Name: Cohort deals routeid wise CS OS - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

/* Route click concentration for Cohort Deals BoostUI analysis Change date_params per day (2026-04-01 .. 2026-04-29). Grain: doi x exp_variant x user_type */ WITH date_params AS ( SELECT TIMESTAMP '2026-04-15 18:30:00' AS start_time, TIMESTAMP '2026-04-16 18:30:00' AS end_time ), srp AS ( SELECT CAST(DATE_TRUNC('day', at_timezone(__time, 'Asia/Kolkata')) AS DATE) AS doi, mri_session_id, route_id, UPPER(user_type) AS user_type, CASE WHEN channel_exp_info IS NULL THEN 'null' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V0') THEN 'V0' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V1') THEN 'V1' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V2') THEN 'V2' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V3') THEN 'V3' WHEN contains(channel_exp_info, 'COHORT_DEALS_SRP_AB:V4') THEN 'V4' ELSE 'others' END AS exp_variant, MAX(CASE WHEN cohort_type = 'BOOSTUI' THEN 1 ELSE 0 END) AS boostui_seen FROM user_interaction.search_route_details s CROSS JOIN date_params d WHERE s.__time >= d.start_time AND s.__time < d.end_time AND channel = 'MOBILE_APP' AND os = 'iOS' AND tp_channel = 'INVALID' AND country = 'IND' AND DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, __time)), doj) = 0 GROUP BY 1, 2, 3, 4, 5 ), session_attrs AS ( SELECT doi, mri_session_id, exp_variant, user_type, MAX(boostui_seen) AS boostui_seen FROM srp WHERE exp_variant IN ('V0', 'V1', 'V2') GROUP BY 1, 2, 3, 4 ), red_deal_rids AS ( SELECT DISTINCT exp_variant, route_id FROM srp WHERE boostui_seen = 1 AND exp_variant IN ('V0', 'V1', 'V2') ), sl_ranked AS ( SELECT s.*, ROW_NUMBER() OVER ( PARTITION BY mri_session_id, route_id, mri_uuid ORDER BY __time DESC ) AS rn FROM user_interaction.seat_layout_details s CROSS JOIN date_params d WHERE s.__time >= d.start_time AND s.__time < d.end_time AND os = 'iOS' AND country = 'IND' AND DATE(DATE_ADD('MINUTE', 330, __time)) = CAST(doj AS DATE) ), sl AS ( SELECT mri_session_id, route_id, CASE WHEN user_origin LIKE 'BOOSTUI%' THEN 1 ELSE 0 END AS sl_entry, 1 AS sl_click FROM sl_ranked WHERE rn = 1 ), sl_labeled AS ( SELECT sa.doi, sa.exp_variant, sa.user_type, sl.route_id, sl.sl_click, CASE WHEN sa.boostui_seen = 1 THEN 1 ELSE 0 END AS in_boosted_session, sl.sl_entry AS is_boostui_entry, CASE WHEN rdr.route_id IS NOT NULL THEN 1 ELSE 0 END AS is_red_deal_rid FROM sl INNER JOIN session_attrs sa ON sl.mri_session_id = sa.mri_session_id LEFT JOIN red_deal_rids rdr ON rdr.exp_variant = sa.exp_variant AND rdr.route_id = sl.route_id ), route_sl AS ( SELECT doi, exp_variant, user_type, route_id, MAX(is_red_deal_rid) AS is_red_deal_rid, SUM(sl_click) AS sl_clicks_all_overall, SUM(CASE WHEN in_boosted_session = 1 THEN sl_click ELSE 0 END) AS sl_clicks_all_boosted_sess, SUM(CASE WHEN in_boosted_session = 1 AND is_boostui_entry = 1 THEN sl_click ELSE 0 END) AS sl_clicks_boostui_boosted_sess, SUM(CASE WHEN in_boosted_session = 1 AND is_red_deal_rid = 1 THEN sl_click ELSE 0 END) AS sl_clicks_red_deal_boosted_sess, SUM(CASE WHEN is_red_deal_rid = 1 THEN sl_click ELSE 0 END) AS sl_clicks_red_deal_overall FROM sl_labeled GROUP BY 1, 2, 3, 4 ), red_deal_catalog AS ( SELECT doi, exp_variant, user_type, COUNT(DISTINCT route_id) AS red_deal_routeids_on_srp FROM srp WHERE boostui_seen = 1 AND exp_variant IN ('V0', 'V1', 'V2') GROUP BY 1, 2, 3 ), route_sl_ranked AS ( SELECT r.*, ROW_NUMBER() OVER ( PARTITION BY doi, exp_variant, user_type ORDER BY sl_clicks_red_deal_boosted_sess DESC, sl_clicks_red_deal_overall DESC ) AS rn_red_deal_boosted_sess, ROW_NUMBER() OVER ( PARTITION BY doi, exp_variant, user_type ORDER BY sl_clicks_red_deal_overall DESC, sl_clicks_red_deal_boosted_sess DESC ) AS rn_red_deal_overall, ROW_NUMBER() OVER ( PARTITION BY doi, exp_variant, user_type ORDER BY sl_clicks_boostui_boosted_sess DESC ) AS rn_boostui_boosted_sess, SUM(sl_clicks_red_deal_boosted_sess) OVER (PARTITION BY doi, exp_variant, user_type) AS tot_red_deal_boosted_sess, SUM(sl_clicks_red_deal_overall) OVER (PARTITION BY doi, exp_variant, user_type) AS tot_red_deal_overall, SUM(sl_clicks_boostui_boosted_sess) OVER (PARTITION BY doi, exp_variant, user_type) AS tot_boostui_boosted_sess, SUM(sl_clicks_all_boosted_sess) OVER (PARTITION BY doi, exp_variant, user_type) AS tot_all_boosted_sess, SUM(sl_clicks_all_overall) OVER (PARTITION BY doi, exp_variant, user_type) AS tot_all_overall FROM route_sl r WHERE is_red_deal_rid = 1 ) SELECT r.doi, r.exp_variant, -- r.user_type, -- 'Overall' AS user_type, /* Route universe */ MAX(c.red_deal_routeids_on_srp) AS red_deal_routeids_on_srp, COUNT(CASE WHEN r.sl_clicks_red_deal_boosted_sess > 0 THEN 1 END) AS red_deal_routeids_with_sl_boosted_sess, COUNT(CASE WHEN r.sl_clicks_red_deal_overall > 0 THEN 1 END) AS red_deal_routeids_with_sl_overall, COUNT(CASE WHEN sl_clicks_red_deal_boosted_sess > 0 AND sl_clicks_red_deal_overall = sl_clicks_red_deal_boosted_sess THEN 1 END) AS red_deal_routes_clicks_only_in_boosted_sess, COUNT(CASE WHEN sl_clicks_red_deal_boosted_sess = 0 AND sl_clicks_red_deal_overall > 0 THEN 1 END) AS red_deal_routes_clicks_only_outside_boosted_sess, COUNT(CASE WHEN sl_clicks_red_deal_boosted_sess > 0 AND sl_clicks_red_deal_overall > sl_clicks_red_deal_boosted_sess THEN 1 END) AS red_deal_routes_clicks_in_both_session_types, /* Click volumes (match your share denominators/numerators) */ MAX(r.tot_boostui_boosted_sess) AS boostui_sl_clicks_boosted_sess, MAX(r.tot_red_deal_boosted_sess) AS red_deal_sl_clicks_boosted_sess, MAX(r.tot_red_deal_overall) AS red_deal_sl_clicks_overall, MAX(r.tot_all_boosted_sess) AS all_sl_clicks_boosted_sess, MAX(r.tot_all_overall) AS all_sl_clicks_overall, /* --- Numerators / denominators (pool across days: SUM(num)/SUM(den)) --- */ MAX(r.tot_boostui_boosted_sess) AS boostui_click_share_num, MAX(r.tot_all_boosted_sess) AS boostui_click_share_den, SUM(CASE WHEN r.rn_red_deal_boosted_sess <= 5 THEN r.sl_clicks_red_deal_boosted_sess ELSE 0 END) AS top5_red_deal_boosted_sess_num, MAX(r.tot_red_deal_boosted_sess) AS top5_red_deal_boosted_sess_den, SUM(CASE WHEN r.rn_red_deal_boosted_sess <= 10 THEN r.sl_clicks_red_deal_boosted_sess ELSE 0 END) AS top10_red_deal_boosted_sess_num, MAX(r.tot_red_deal_boosted_sess) AS top10_red_deal_boosted_sess_den, SUM(CASE WHEN r.rn_red_deal_overall <= 5 THEN r.sl_clicks_red_deal_overall ELSE 0 END) AS top5_red_deal_overall_num, MAX(r.tot_red_deal_overall) AS top5_red_deal_overall_den, SUM(CASE WHEN r.rn_red_deal_overall <= 10 THEN r.sl_clicks_red_deal_overall ELSE 0 END) AS top10_red_deal_overall_num, MAX(r.tot_red_deal_overall) AS top10_red_deal_overall_den, SUM(CASE WHEN r.rn_red_deal_boosted_sess <= 10 THEN r.sl_clicks_red_deal_overall ELSE 0 END) AS top10_boosted_sess_routes_overall_num, MAX(r.tot_red_deal_overall) AS top10_boosted_sess_routes_overall_den, COUNT(CASE WHEN r.sl_clicks_red_deal_boosted_sess > 0 AND r.sl_clicks_red_deal_overall > 0 THEN 1 END) AS route_jaccard_num, COUNT(CASE WHEN r.sl_clicks_red_deal_overall > 0 THEN 1 END) AS route_jaccard_den, /* Shares (sanity check vs GSheets) */ ROUND(1.0 * MAX(r.tot_boostui_boosted_sess) / NULLIF(MAX(r.tot_all_boosted_sess), 0), 4) AS boostui_click_share_pct, -- ROUND(1.0 * MAX(r.tot_red_deal_boosted_sess) / NULLIF(MAX(r.tot_all_boosted_sess), 0), 4) AS boosted_click_share_pct, -- ROUND(1.0 * MAX(r.tot_red_deal_overall) / NULLIF(MAX(r.tot_all_overall), 0), 4) AS overall_click_share_pct, /* Concentration among red-deal routeids with SL clicks */ ROUND(1.0 * SUM(CASE WHEN r.rn_red_deal_boosted_sess <= 5 THEN r.sl_clicks_red_deal_boosted_sess ELSE 0 END) / NULLIF(MAX(r.tot_red_deal_boosted_sess), 0), 4) AS top5_red_deal_share_of_boosted_sess_pct, ROUND(1.0 * SUM(CASE WHEN r.rn_red_deal_boosted_sess <= 10 THEN r.sl_clicks_red_deal_boosted_sess ELSE 0 END) / NULLIF(MAX(r.tot_red_deal_boosted_sess), 0), 4) AS top10_red_deal_share_of_boosted_sess_pct, ROUND(1.0 * SUM(CASE WHEN r.rn_red_deal_overall <= 5 THEN r.sl_clicks_red_deal_overall ELSE 0 END) / NULLIF(MAX(r.tot_red_deal_overall), 0), 4) AS top5_red_deal_share_of_overall_pct, ROUND(1.0 * SUM(CASE WHEN r.rn_red_deal_overall <= 10 THEN r.sl_clicks_red_deal_overall ELSE 0 END) / NULLIF(MAX(r.tot_red_deal_overall), 0), 4) AS top10_red_deal_share_of_overall_pct, /* Do top boosted-session routeids also dominate overall? */ ROUND(1.0 * SUM(CASE WHEN r.rn_red_deal_boosted_sess <= 10 THEN r.sl_clicks_red_deal_overall ELSE 0 END) / NULLIF(MAX(r.tot_red_deal_overall), 0), 4) AS top10_boosted_sess_routeids_share_of_all_red_deal_clicks_pct, /* Route-set overlap (Jaccard on routeids with >=1 click) */ ROUND( 1.0 * COUNT(CASE WHEN r.sl_clicks_red_deal_boosted_sess > 0 AND r.sl_clicks_red_deal_overall > 0 THEN 1 END) / NULLIF( COUNT(CASE WHEN r.sl_clicks_red_deal_boosted_sess > 0 THEN 1 END) + COUNT(CASE WHEN r.sl_clicks_red_deal_overall > 0 THEN 1 END) - COUNT(CASE WHEN r.sl_clicks_red_deal_boosted_sess > 0 AND r.sl_clicks_red_deal_overall > 0 THEN 1 END), 0 ), 4 ) AS route_jaccard_overlap_pct FROM route_sl_ranked r LEFT JOIN red_deal_catalog c ON c.doi = r.doi AND c.exp_variant = r.exp_variant AND c.user_type = r.user_type GROUP BY 1, 2 ORDER BY 1, 2
